package geozarr

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"io"
	"strings"
	"sync"
)

//go:generate .venv/bin/python -I consistency/gen_crs_meta.py

// crs_meta.json.gz holds, for every built-in code, the WKT GDAL writes
// for its CRS and the grid mapping attributes rioxarray's write_crs gives
// it (generated by consistency/gen_crs_meta.py from rasterio, pyproj and
// rioxarray).
//
//go:embed crs_meta.json.gz
var crsMetaGz []byte

type crsMeta struct {
	WKT   string  `json:"wkt"`
	Attrs [][]any `json:"attrs"`
}

var crsMetaOnce = sync.OnceValues(func() (map[string]crsMeta, error) {
	zr, err := gzip.NewReader(bytes.NewReader(crsMetaGz))
	if err != nil {
		return nil, err
	}
	b, err := io.ReadAll(zr)
	if err != nil {
		return nil, err
	}
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber() // keep Python's float spellings
	var m map[string]crsMeta
	return m, dec.Decode(&m)
})

// metaOf returns the WKT and grid mapping attributes of a built-in code.
func metaOf(code string) (crsMeta, bool) {
	m, err := crsMetaOnce()
	if err != nil {
		return crsMeta{}, false
	}
	e, ok := m[strings.ToUpper(code)]
	return e, ok
}

// gridMappingAttrs returns e's attributes as Attrs.
func (e crsMeta) gridMappingAttrs() Attrs {
	out := make(Attrs, 0, len(e.Attrs))
	for _, kv := range e.Attrs {
		k, _ := kv[0].(string)
		out = append(out, Attr{k, kv[1]})
	}
	return out
}
